begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;select plan(22);
select ok((select bool_and(rowsecurity) from pg_tables where schemaname='public' and tablename in ('courses','course_categories','course_levels','classrooms','academic_configuration_events')),'Academic tables enforce RLS');
select ok(not has_column_privilege('authenticated','public.courses','standard_price','select'),'Raw NUMERIC prices are not exposed');
select ok(not has_table_privilege('authenticated','public.academic_configuration_events','select'),'Raw command receipts remain private');
select ok(not has_table_privilege('authenticated','public.classrooms','update'),'Classroom writes require checked commands');
create temporary table academic_scope(label text primary key,id uuid);grant select,insert on academic_scope to authenticated;
insert into auth.users(id,email) values('99999500-0000-0000-0000-000000000001','native-academic-owner@example.test'),('99999500-0000-0000-0000-000000000002','native-academic-teacher@example.test'),('99999500-0000-0000-0000-000000000003','native-academic-other@example.test');
set local role authenticated;set local request.jwt.claim.sub='99999500-0000-0000-0000-000000000001';
insert into academic_scope select 'tenant',public.create_business('Native academic configuration');
insert into academic_scope select 'branch',id from public.branches where tenant_id=(select id from academic_scope where label='tenant') limit 1;
insert into public.branches(tenant_id,name) select id,'Other academic branch' from academic_scope where label='tenant';
insert into academic_scope select 'second',id from public.branches where tenant_id=(select id from academic_scope where label='tenant') and name='Other academic branch';
insert into academic_scope select 'category',public.save_course_setting((select id from academic_scope where label='tenant'),'category',null,gen_random_uuid(),0,'Languages');
insert into academic_scope select 'course',public.save_course((select id from academic_scope where label='tenant'),null,'99999500-0000-0000-0000-000000000010',0,jsonb_build_object('name','Native English','code','NATIVE','category_id',(select id from academic_scope where label='category'),'standard_price','9007199254740993.01','pricing_model','monthly'));
select is(public.course_details((select id from academic_scope where label='tenant'),(select id from academic_scope where label='course'))->'course'->>'standard_price','9007199254740993.01','Price is an exact decimal string');
select is(public.save_course((select id from academic_scope where label='tenant'),null,'99999500-0000-0000-0000-000000000010',0,jsonb_build_object('name','Native English','code','NATIVE','category_id',(select id from academic_scope where label='category'),'standard_price','9007199254740993.01','pricing_model','monthly')),(select id from academic_scope where label='course'),'Retry preserves course identity');
select throws_ok($$select public.save_course((select id from academic_scope where label='tenant'),(select id from academic_scope where label='course'),gen_random_uuid(),0,'{"name":"Stale","standard_price":"10","pricing_model":"monthly"}')$$,'40001',null,'Stale course edits fail');
select public.set_academic_active((select id from academic_scope where label='tenant'),'course',(select id from academic_scope where label='course'),gen_random_uuid(),1,false,'Archive');
select is(public.course_directory((select id from academic_scope where label='tenant'))->>'total','0','Archived courses leave the active directory');
select is(public.course_directory((select id from academic_scope where label='tenant'),'{"status":"inactive"}')->>'total','1','Archived courses are retained and filterable');
select is(public.academic_configuration_history((select id from academic_scope where label='tenant'),'course',(select id from academic_scope where label='course'))->>'total','2','Before/after history is retained');
insert into academic_scope select 'room',public.save_classroom((select id from academic_scope where label='tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',(select id from academic_scope where label='branch'),'name','Room 1','capacity','12'));
insert into academic_scope select 'hidden',public.save_classroom((select id from academic_scope where label='tenant'),null,gen_random_uuid(),0,jsonb_build_object('branch_id',(select id from academic_scope where label='second'),'name','Hidden room','capacity','15'));
select is(public.classroom_details((select id from academic_scope where label='tenant'),(select id from academic_scope where label='room'))->'classroom'->>'capacity','12','Real classroom capacity is persisted');
select throws_ok($$select public.save_classroom((select id from academic_scope where label='tenant'),(select id from academic_scope where label='room'),gen_random_uuid(),1,jsonb_build_object('branch_id',(select id from academic_scope where label='second'),'name','Moved','capacity','12'))$$,'P0001','Classroom branch cannot change','Room scope cannot be moved');
select public.assign_member_role((select id from academic_scope where label='tenant'),'99999500-0000-0000-0000-000000000002',(select id from public.business_roles where tenant_id=(select id from academic_scope where label='tenant') and system_key='teacher'),array[(select id from academic_scope where label='branch')]);
set local request.jwt.claim.sub='99999500-0000-0000-0000-000000000002';
select is(public.course_details((select id from academic_scope where label='tenant'),(select id from academic_scope where label='course'))->>'can_manage','false','Teacher reads catalog without management');
select is(public.classroom_directory((select id from academic_scope where label='tenant'))->>'total','1','Teacher sees assigned branch rooms only');
select throws_ok($$select public.classroom_details((select id from academic_scope where label='tenant'),(select id from academic_scope where label='hidden'))$$,'42501','Classroom access denied','Forged classroom ID denied');
select throws_ok($$select public.save_course((select id from academic_scope where label='tenant'),null,gen_random_uuid(),0,'{"name":"Denied","standard_price":"1","pricing_model":"monthly"}')$$,'42501','Business-wide course management denied','Teacher cannot change shared catalog');
select throws_ok($$select public.set_academic_active((select id from academic_scope where label='tenant'),'classroom',(select id from academic_scope where label='room'),gen_random_uuid(),1,false)$$,'42501','Classroom status change denied','Teacher cannot deactivate classrooms');
select throws_ok($$select public.financial_report((select id from academic_scope where label='tenant'),'payments')$$,'42501',null,'Academic grants expose no financial reports');
select throws_ok($$select * from public.employee_salary_settings$$,'42501',null,'Academic grants expose no salaries');
set local request.jwt.claim.sub='99999500-0000-0000-0000-000000000003';
select throws_ok($$select public.course_directory((select id from academic_scope where label='tenant'))$$,'42501','Course catalog access denied','Other tenant user cannot read catalog');
select is((select count(*)::integer from public.courses),0,'Direct metadata RLS isolates other tenants');
set local request.jwt.claim.sub='';
select throws_ok($$select public.classroom_details((select id from academic_scope where label='tenant'),(select id from academic_scope where label='room'))$$,'42501','Classroom access denied','Subjectless classroom access denied');
reset role;select * from finish();rollback;
